    deniedTitle: "\u092E\u093E\u0907\u0915\u094D\u0930\u094B\u092B\u093C\u094B\u0928 \u092C\u0902\u0926 \u0939\u0948",
    deniedBody: "\u0906\u092A\u0915\u0940 \u092E\u093E\u0907\u0915\u094D\u0930\u094B\u092B\u093C\u094B\u0928 \u0905\u0928\u0941\u092E\u0924\u093F \u092C\u0902\u0926 \u0915\u0930 \u0926\u0940 \u0917\u0908\u0964 \u0926\u094B\u092C\u093E\u0930\u093E \u091A\u093E\u0932\u0942 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u092A\u0947\u091C \u0915\u0947 \u090A\u092A\u0930 \u0924\u093E\u0932\u093E \u092F\u093E \u0938\u0947\u091F\u093F\u0902\u0917 \u0915\u0947 \u0928\u093F\u0936\u093E\u0928 \u0915\u094B \u0926\u092C\u093E\u090F\u0901, \u092B\u093F\u0930 \u092E\u093E\u0907\u0915\u094D\u0930\u094B\u092B\u093C\u094B\u0928 \u0915\u0940 \u0905\u0928\u0941\u092E\u0924\u093F \u0926\u0947\u0902\u0964",
    noSpeechTitle: "\u092E\u0941\u091D\u0947 \u0915\u0941\u091B \u0938\u0941\u0928\u093E\u0908 \u0928\u0939\u0940\u0902 \u0926\u093F\u092F\u093E",
