    networkTitle: "\u092E\u0948\u0902 \u0905\u092D\u0940 \u0928\u0939\u0940\u0902 \u0938\u0941\u0928 \u0938\u0915\u0924\u093E",
    networkBody: "\u092C\u094B\u0932\u0915\u0930 \u0932\u093F\u0916\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0907\u0902\u091F\u0930\u0928\u0947\u091F \u091A\u093E\u0939\u093F\u090F\u0964 \u0915\u0943\u092A\u092F\u093E \u0907\u0938\u0915\u0947 \u092C\u091C\u093E\u092F \u0932\u093F\u0916 \u0926\u0947\u0902, \u092E\u0948\u0902 \u0906\u0917\u0947 \u092C\u0922\u093C \u091C\u093E\u090A\u0901\u0917\u093E\u0964",
    notSecureTitle: "\u0938\u0941\u0928\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 \u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u091A\u093E\u0939\u093F\u090F",
    notSecureBody: "\u092C\u094D\u0930\u093E\u0909\u091C\u093C\u0930 \u092E\u093E\u0907\u0915\u094D\u0930\u094B\u092B\u093C\u094B\u0928 \u0938\u093F\u0930\u094D\u092B\u093C \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 (https) \u092F\u093E localhost \u092A\u0947\u091C \u092A\u0930 \u0926\u0947\u0924\u0947 \u0939\u0948\u0902\u0964 \u0915\u0943\u092A\u092F\u093E \u0905\u092D\u0940 \u0932\u093F\u0916\u0915\u0930 \u092C\u0924\u093E\u090F\u0901\u0964"
