      safeAction: "\u0B89\u0B9F\u0BA9\u0BC7 \u0BA4\u0BCA\u0B9F\u0BB0\u0BCD\u0BAA\u0BC8 \u0BA8\u0BBF\u0BB1\u0BC1\u0BA4\u0BCD\u0BA4\u0BC1\u0B99\u0BCD\u0B95\u0BB3\u0BCD. \u0B85\u0BB1\u0BBF\u0BAF\u0BBE\u0BA4 \u0BA8\u0BAA\u0BB0\u0BC1\u0B9F\u0BA9\u0BCD \u0BA4\u0BBF\u0BB0\u0BC8\u0BAF\u0BC8 \u0B92\u0BB0\u0BC1\u0BAA\u0BCB\u0BA4\u0BC1\u0BAE\u0BCD \u0BAA\u0B95\u0BBF\u0BB0 \u0BB5\u0BC7\u0BA3\u0BCD\u0B9F\u0BBE\u0BAE\u0BCD."
