    needAccount: "\u0B8E\u0BA9\u0B95\u0BCD\u0B95\u0BC1 \u0B95\u0BA3\u0B95\u0BCD\u0B95\u0BC1 \u0B87\u0BB2\u0BCD\u0BB2\u0BC8",
    helpTitle: "\u0BB5\u0BC7\u0BB1\u0BCA\u0BB0\u0BC1\u0BB5\u0BB0\u0BC1\u0B95\u0BCD\u0B95\u0BBE\u0B95 \u0B85\u0BAE\u0BC8\u0BAA\u0BCD\u0BAA\u0BA4\u0BC1",
    help1: "1. \u0B89\u0B99\u0BCD\u0B95\u0BB3\u0BCD \u0B9A\u0BCA\u0BB2\u0BCD\u0BB2\u0BC1\u0BAE\u0BCD \u0BAE\u0BBF\u0BA9\u0BCD\u0BA9\u0B9E\u0BCD\u0B9A\u0BB2\u0BC1\u0B9F\u0BA9\u0BCD \u0B89\u0BB3\u0BCD\u0BA8\u0BC1\u0BB4\u0BC8\u0BB5\u0BC1\u0BAE\u0BCD, \u0B87\u0BB5\u0BCD\u0BB5\u0BAE\u0BC8\u0BAA\u0BCD\u0BAA\u0BC1\u0B95\u0BB3\u0BC8 \u0BAF\u0BBE\u0BB0\u0BCD \u0BAE\u0BBE\u0BB1\u0BCD\u0BB1\u0BBF\u0BA9\u0BB0\u0BCD \u0B8E\u0BA9\u0BCD\u0BAA\u0BA4\u0BC1 \u0BAA\u0BA4\u0BBF\u0BB5\u0BBE\u0B95\u0BC1\u0BAE\u0BCD.",
