      safeAction: "\u09AE\u09C1\u099B\u09C7 \u09A6\u09BF\u09A8\u0964 \u0995\u09CB\u09A8\u09CB \u09AA\u09CD\u09B0\u09B8\u09C7\u09B8\u09BF\u0982 \u09AB\u09BF \u09AC\u09BE \u09AC\u09CD\u09AF\u09BE\u0982\u0995\u09C7\u09B0 \u09A4\u09A5\u09CD\u09AF \u09AA\u09BE\u09A0\u09BE\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964"
