      safeAction: "\u09A8\u09BF\u099C\u09C7 \u09AC\u09CD\u09AF\u09BE\u0982\u0995\u09BF\u0982 \u0985\u09CD\u09AF\u09BE\u09AA \u0996\u09C1\u09B2\u09C7 KYC-\u098F\u09B0 \u09AC\u09BF\u099C\u09CD\u099E\u09AA\u09CD\u09A4\u09BF \u09A6\u09C7\u0996\u09C1\u09A8\u0964 \u09AC\u09BE\u09B0\u09CD\u09A4\u09BE\u09B0 \u09B2\u09BF\u0982\u0995 \u09AC\u09BE \u09AB\u09CB\u09A8 \u09A8\u09AE\u09CD\u09AC\u09B0 \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u0995\u09B0\u09AC\u09C7\u09A8 \u09A8\u09BE\u0964"
